class AerodromeSurfaceWind(AerodromeSurfaceWindType):
    """
    An aggregation of surface wind conditions typically reported together at an aerodrome, including wind direction
    information, wind speed, and wind gusts.

    Wind direction is reported according to ICAO PANS-MET (Doc 10157) Section 2.2.1.5.2 b): "variations from the
    mean wind direction during the past 10 minutes shall be reported as follows, if the total variation is 60° or
    more: 1) when the total variation is 60° or more and less than 180° and the wind speed is 1.5 m/s (3 kt) or
    more, such directional variations shall be reported as the two extreme directions between which the surface wind
    has varied; 2) when the total variation is 60° or more and less than 180° and the wind speed is less than 1.5
    m/s (3 kt), the wind direction shall be reported as variable with no mean wind direction; or 3) when the total
    variation is 180° or more, the wind direction shall be reported as variable with no mean wind direction" Wind
    direction shall be given in degrees from true North. Plane angle unit of measure (uom) is "deg". A true north
    wind is indicated with a direction of 360. Calm wind is indicated with a direction of 0. Wind speeds and gusts,
    if present, shall be provided in either two units of measures: "m/s" or "[kn_i]" (knot).
    """

    class Meta:
        namespace = "http://icao.int/iwxxm/2025-2"

    model_config = ConfigDict(defer_build=True)


