class Metar(Metartype):
    """
    A routine observation made at an aerodrome throughout the day.

    METAR observations are made (and distributed) at intervals of one hour or, if so determined by regional air
    navigation agreement, at intervals of one half-hour. The information contained in METAR and SPECI is identical.
    SPECI is issued when conditions merit a non-routine report on conditions at an aerodrome. METARs are a routine
    report produced for dissemination beyond the aerodrome of origin, and are mainly intended for flight planning,
    VOLMET broadcasts and D-VOLMET. See ICAO Annex 3 and PANS-MET (Doc 10157).
    """

    class Meta:
        name = "METAR"
        namespace = "http://icao.int/iwxxm/2025-2"

    model_config = ConfigDict(defer_build=True)


